from pathlib import Path
out=Path('public/media/vector');out.mkdir(parents=True,exist_ok=True)
def svg(body,w=1920,h=1080):
 return f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}" role="img"><defs><linearGradient id="paper" x2="1" y2="1"><stop stop-color="#fcfcf5"/><stop offset="1" stop-color="#e7eddf"/></linearGradient><linearGradient id="forest" x2="1" y2=".8"><stop stop-color="#447560"/><stop offset=".5" stop-color="#214f40"/><stop offset="1" stop-color="#10362e"/></linearGradient><linearGradient id="blue" x2="1" y2=".2"><stop stop-color="#4b8da6"/><stop offset=".4" stop-color="#83b5c3"/><stop offset="1" stop-color="#32667e"/></linearGradient><linearGradient id="steel" x2="1"><stop stop-color="#718c89"/><stop offset=".4" stop-color="#ecf0e7"/><stop offset="1" stop-color="#6c8985"/></linearGradient><filter id="shadow" x="-50%" y="-50%" width="200%" height="220%"><feDropShadow dx="0" dy="20" stdDeviation="20" flood-color="#193c2d" flood-opacity=".12"/></filter><filter id="smallshadow" x="-50%" y="-50%" width="200%" height="220%"><feDropShadow dx="0" dy="8" stdDeviation="7" flood-color="#193c2d" flood-opacity=".13"/></filter></defs>{body}</svg>'''
def text(x,y,t,size=24,fill='#214b3c',extra=''):
 return f'<text x="{x}" y="{y}" fill="{fill}" font-family="Arial,Helvetica,sans-serif" font-size="{size}" {extra}>{t}</text>'
def tag(x=0,y=0,s=1):
 return f'''<g id="enclosed-smart-tag" transform="translate({x} {y}) scale({s})" filter="url(#shadow)"><rect x="0" y="0" width="260" height="350" rx="65" fill="url(#forest)"/><rect x="12" y="12" width="236" height="326" rx="56" fill="none" stroke="#a9c3a5" stroke-opacity=".35"/><circle cx="130" cy="48" r="18" fill="#f2f3e7"/><path d="M130 15 C75 -65 220 -65 164 20" fill="none" stroke="url(#steel)" stroke-width="13"/><g transform="translate(70 104)" fill="none" stroke="#e6efd7" stroke-width="10" stroke-linecap="round"><path d="M43 16 Q92 63 43 110"/><path d="M19 36 Q49 63 19 90"/><circle cx="0" cy="63" r="5" fill="#e6efd7" stroke="none"/></g>{text(130,280,'FINDBOX',27,'#eff4e6','text-anchor="middle" letter-spacing="2"')}{text(130,310,'SMART LABEL',12,'#b9ceac','text-anchor="middle" letter-spacing="3"')}</g>'''
def bottle(x=0,y=0,s=1):
 return f'''<g id="bottle" transform="translate({x} {y}) scale({s})" filter="url(#shadow)"><path d="M54 60 Q33 62 33 95 L33 127 Q0 157 0 202 V505 Q0 545 43 545 H167 Q210 545 210 505 V202 Q210 157 177 127 V95 Q177 62 156 60Z" fill="url(#blue)"/><rect x="33" y="64" width="144" height="56" rx="12" fill="url(#steel)"/><rect x="31" y="35" width="148" height="42" rx="15" fill="#d8bf94"/><path d="M42 39 V16 Q42 -12 70 -12 H140 Q168 -12 168 16 V39" fill="none" stroke="url(#steel)" stroke-width="11"/><path d="M28 210 V463" stroke="#d2edf0" stroke-opacity=".24" stroke-width="11" stroke-linecap="round"/><rect x="51" y="273" width="108" height="112" rx="16" fill="#fafbf2"/><g transform="translate(66 289)" fill="#214b3c"><path d="M0 0H28V28H0ZM50 0H78V28H50ZM0 50H28V78H0Z"/><path d="M7 7H21V21H7ZM57 7H71V21H57ZM7 57H21V71H7Z" fill="#fafbf2"/><path d="M38 38H50V50H38ZM62 38H78V50H62ZM38 62H50V78H38ZM62 62H78V78H62Z"/></g></g>'''
def phone(x=0,y=0,s=1):
 return f'''<g id="phone" transform="translate({x} {y}) scale({s})" filter="url(#shadow)"><rect width="310" height="590" rx="46" fill="#23463e"/><rect x="8" y="8" width="294" height="574" rx="39" fill="#f9faf4"/><rect x="99" y="19" width="112" height="22" rx="11" fill="#23463e"/>{text(29,95,'FindBox',30,extra='font-weight="600"')}{text(29,128,'YOUR WAY HOME',12,'#71876c','letter-spacing="2"')}<rect x="24" y="155" width="262" height="227" rx="25" fill="#e3eddf"/><circle cx="155" cy="249" r="53" fill="#245842"/><path d="M130 249L148 267L180 231" fill="none" stroke="#e6f1d8" stroke-width="10" stroke-linecap="round" stroke-linejoin="round"/>{text(155,338,'Found. Safely received.',17,extra='text-anchor="middle"')}<rect x="24" y="403" width="262" height="99" rx="22" fill="#fff" stroke="#dfe7d7"/>{text(42,436,'School reception',19)}{text(42,467,'Collection details in your account',12,'#71876c')}<rect x="95" y="554" width="120" height="5" rx="3" fill="#214b3c"/></g>'''
# Standalone enclosed NFC tag replaces all exposed coil imagery.
out.joinpath('smart-tag.svg').write_text(svg('<ellipse cx="400" cy="710" rx="188" ry="32" fill="#193c2d" opacity=".09"/>'+tag(240,160,1.25),800,800),encoding='utf-8')
# Layered main explainer key art, each group can be animated independently.
body='<g id="background"><rect width="1920" height="1080" fill="url(#paper)"/><circle cx="1470" cy="470" r="440" fill="#dce7d2" opacity=".55"/><ellipse cx="1370" cy="870" rx="400" ry="48" fill="#214b3c" opacity=".06"/></g>'
body+='<g id="brand">'+text(115,120,'FINDBOX',34,extra='font-weight="600" letter-spacing="-2"')+'</g><g id="headline">'+text(110,380,'Every belonging.',78,extra='letter-spacing="-4"')+text(110,473,'A way home.',78,extra='letter-spacing="-4"')+text(115,543,'Little labels. Connected schools. Happier reunions.',23,'#6d8068')+'</g>'
body+='<g id="connection-orbit"><ellipse cx="1310" cy="535" rx="465" ry="302" fill="none" stroke="#a7b99a" stroke-dasharray="4 13" stroke-width="2"/></g>'+phone(1190,222,1.08)+bottle(887,405,.75)+tag(1570,390,.72)
body+='<g id="private-update" filter="url(#smallshadow)"><rect x="1445" y="206" width="330" height="98" rx="25" fill="#fff"/><circle cx="1495" cy="255" r="23" fill="#e2ecd8"/><path d="M1484 255 L1493 264 L1508 246" fill="none" stroke="#28503e" stroke-width="4"/>'+text(1537,248,'Your item is found.',18)+text(1537,274,'School-confirmed return',14,'#73856b')+'</g><g id="closing-tagline">'+text(115,906,'LESS LOST. MORE FOUND.',16,'#68835d','letter-spacing="4"')+text(115,953,'findbox.africa',25)+'</g>'
out.joinpath('explainer-key-art.svg').write_text(svg(body),encoding='utf-8')
# Isometric campus: layered buildings, footpaths, collection stations and landscape.
def building(name,x,y,w,h,color):
 windows=''.join(f'<rect x="{x+18+i*39}" y="{y+38+j*37}" width="24" height="22" rx="3" fill="#9ab9ae" stroke="#eaf1e4" stroke-width="3"/>' for i in range((w-30)//39) for j in range(2))
 return f'<g id="{name}"><path d="M{x} {y}L{x+42} {y-32}H{x+w+42}L{x+w} {y}Z" fill="#e6ddc4"/><path d="M{x+w} {y}L{x+w+42} {y-32}V{y+h-32}L{x+w} {y+h}Z" fill="#bdc9ac"/><rect x="{x}" y="{y}" width="{w}" height="{h}" rx="4" fill="{color}"/>{windows}<rect x="{x+w-48}" y="{y+h-49}" width="28" height="49" rx="4" fill="#3b6551"/></g>'
def tree(x,y,s=1):
 return f'<g transform="translate({x} {y}) scale({s})"><ellipse cx="8" cy="47" rx="39" ry="13" fill="#214b3c" opacity=".08"/><path d="M0 7V46" stroke="#8c8d65" stroke-width="9"/><ellipse cy="-8" rx="31" ry="42" fill="#8faa78"/><ellipse cx="-8" cy="-18" rx="21" ry="32" fill="#b6c99c"/></g>'
def pin(id,x,y,label):
 return f'<g id="{id}" filter="url(#smallshadow)"><circle cx="{x}" cy="{y}" r="37" fill="#fff"/><circle cx="{x}" cy="{y}" r="28" fill="#214f40"/><path d="M{x} {y+17}C{x-27} {y-9} {x-9} {y-26} {x+5} {y-18}C{x+24} {y-10} {x+9} {y+8} {x} {y+17}Z" fill="none" stroke="#f6f8ef" stroke-width="3"/><circle cx="{x}" cy="{y-5}" r="5" fill="#f6f8ef"/>'+text(x,y+71,label,18,extra='text-anchor="middle"')+'</g>'
c='<g id="background"><rect width="1920" height="1080" rx="48" fill="url(#paper)"/></g><g id="campus-ground"><path d="M170 580L995 170L1770 550L945 980Z" fill="#dce6cb"/><path d="M170 580V606L945 1006L1770 576V550L945 980Z" fill="#becfa8"/></g>'
c+='<g id="walking-routes" fill="none" stroke="#f7f4e5" stroke-width="29" stroke-linecap="round" stroke-linejoin="round"><path d="M560 680 L980 465 L1400 675 M980 465V770"/></g><g id="route-trace" fill="none" stroke="#8fa777" stroke-width="3" stroke-dasharray="7 13"><path d="M560 680L980 465L1400 675M980 465V770"/></g>'
c+=building('classrooms',530,360,275,146,'#f5edda')+building('library',1200,390,216,140,'#f3eedc')+building('school-office',630,670,220,133,'#e9e6ce')
c+='<g id="sports-field" transform="translate(1160 700) rotate(-26)"><rect width="290" height="148" rx="17" fill="#a9bd8d" stroke="#8ea976" stroke-width="4"/><rect x="16" y="14" width="258" height="120" rx="2" fill="none" stroke="#e8efdb" stroke-width="2"/><path d="M145 14V134" stroke="#e8efdb" stroke-width="2"/><circle cx="145" cy="74" r="27" fill="none" stroke="#e8efdb" stroke-width="2"/><path d="M16 42H52V106H16M274 42H238V106H274" fill="none" stroke="#e8efdb" stroke-width="2"/></g>'
c+='<g id="landscape">'+''.join(tree(x,y,s) for x,y,s in [(405,550,1.2),(940,320,.95),(1040,350,.8),(1570,600,1.2),(980,885,.8),(370,650,.85),(1100,825,.6)])+'</g>'
c+=pin('reception-pin',590,640,'MAIN RECEPTION')+pin('library-pin',1160,480,'LIBRARY DESK')+pin('sports-pin',1460,710,'SPORTS OFFICE')
c+='<g id="campus-heading">'+text(100,115,'A familiar place. A safe return.',48,extra='letter-spacing="-2"')+text(103,157,'Your school sets the collection points.',23,'#738369')+'</g><g id="campus-brand">'+text(1520,987,'FINDBOX',27,extra='letter-spacing="-1"')+'</g>'
out.joinpath('school-campus.svg').write_text(svg(c),encoding='utf-8')
# Separate objects for the motion designer.
for name,art,w,h in [('bottle',bottle(160,80,1.1),600,800),('phone',phone(120,80,1.05),600,800)]:
 out.joinpath(name+'.svg').write_text(svg(art,w,h),encoding='utf-8')
print('Created layered SVG key art, campus and separated product objects.')

# Distinct marketing compositions; catalog product photography stays with its product record.
artworks=[tag(230,180,1.15),bottle(280,175,1.05),phone(230,120,.95),tag(190,220,.85)+tag(430,350,.55),bottle(200,260,.78)+tag(460,280,.7)]
for i,art in enumerate(artworks):
 out.joinpath('stream-'+str(i+1)+'.svg').write_text(svg('<rect width="800" height="1000" rx="35" fill="url(#paper)"/><circle cx="400" cy="450" r="300" fill="#dbe5d1" opacity=".5"/>'+art,800,1000),encoding='utf-8')
